@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted">
                    Items below minimum level&ensp;
                    @if (_isPolling)
                    {
                        <span class="spinner-border spinner-border-sm" role="status"></span>
                    }
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Active — every 10 s</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Stopped</span>
                    }
                </p>
                @if (_lastRefresh.HasValue)
                {
                    <p class="text-muted small">Last refresh: @_lastRefresh.Value.ToString("HH:mm:ss")</p>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime? _lastRefresh;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;

        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        // Cancel any existing polling loop before starting a new one
        await StopPollingAsync();

        _cts = new CancellationTokenSource();
        _isPolling = true;

        var token = _cts.Token;
        var warehouseId = WarehouseState.CurrentWarehouseId;

        // Fire an initial fetch immediately
        await AlertService.RefreshAlertCountAsync(warehouseId);
        _lastRefresh = DateTime.Now;

        // Start the periodic polling loop on a background thread
        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            try
            {
                while (await timer.WaitForNextTickAsync(token))
                {
                    await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
                    _lastRefresh = DateTime.Now;
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on disposal or warehouse switch
            }
        }, token);
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _isPolling = false;
    }

    private async Task HandleWarehouseChanged()
    {
        // Restart polling with the new warehouse
        await StartPollingAsync();
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

